        // Generate video link
        if (appointment.getVideoLink() == null && appointment.getPatientId() != null && appointment.getDoctorId() != null) {
            String patientId = appointment.getPatientId().length() >= 8
                    ? appointment.getPatientId().substring(0, 8)
